// ─── SPLASH SCREEN ─────────────────────────────────────────────────────────────
const LOGO_SRC = "data:image/jpeg;base64,";

function SplashScreen({ out }) {
  return (
    <div style={{
      position: "fixed", inset: 0,
      background: "#f7f6f3",
      display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center",
      zIndex: 9999,
      opacity: out ? 0 : 1,
      transform: out ? "scale(1.012)" : "scale(1)",
      transition: "opacity 0.6s ease, transform 0.6s ease",
      userSelect: "none",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&family=DM+Mono:wght@400&display=swap');
        @keyframes splashFadeUp {
          from { opacity: 0; transform: translateY(18px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @keyframes splashDot {
          0%, 80%, 100% { transform: scale(0.55); opacity: 0.3; }
          40%            { transform: scale(1);    opacity: 1;   }
        }
        @keyframes splashRing {
          from { transform: rotate(0deg); }
          to   { transform: rotate(360deg); }
        }
        .sp-logo  { animation: splashFadeUp 0.7s cubic-bezier(0.22,1,0.36,1) 0.1s both; }
        .sp-name  { animation: splashFadeUp 0.7s cubic-bezier(0.22,1,0.36,1) 0.35s both; }
        .sp-tag   { animation: splashFadeUp 0.7s cubic-bezier(0.22,1,0.36,1) 0.52s both; }
        .sp-load  { animation: splashFadeUp 0.5s ease 0.75s both; }
      `}</style>

      {/* Subtle background grain texture */}
      <div style={{
        position: "absolute", inset: 0, pointerEvents: "none",
        backgroundImage: "radial-gradient(circle at 30% 20%, rgba(255,255,255,0.9) 0%, transparent 60%), radial-gradient(circle at 75% 80%, rgba(235,232,224,0.6) 0%, transparent 55%)",
      }} />

      {/* Logo */}
      <div className="sp-logo" style={{ marginBottom: 20, position: "relative" }}>
        {/* Soft glow ring behind logo */}
        <div style={{
          position: "absolute", inset: -12,
          borderRadius: "50%",
          background: "radial-gradient(circle, rgba(180,170,150,0.18) 0%, transparent 70%)",
        }} />
        <img
          src={LOGO_SRC}
          alt="Prayaas"
          style={{
            width: 110, height: 110,
            objectFit: "contain",
            borderRadius: 24,
            boxShadow: "0 8px 32px rgba(0,0,0,0.10), 0 2px 8px rgba(0,0,0,0.06)",
            background: "#ffffff",
            padding: 10,
          }}
        />
      </div>

      {/* App name */}
      <div className="sp-name" style={{
        fontFamily: "'DM Sans', sans-serif",
        fontSize: 28,
        fontWeight: 700,
        color: "#1a1917",
        letterSpacing: "-0.03em",
        marginBottom: 8,
      }}>
        Prayaas<span style={{ color: "#8a847a", fontWeight: 400 }}>.</span>
      </div>

      {/* Tagline */}
      <div className="sp-tag" style={{
        fontFamily: "'DM Sans', sans-serif",
        fontSize: 14,
        color: "#78716c",
        letterSpacing: "0.01em",
        fontWeight: 400,
        marginBottom: 52,
      }}>
        Find a Topic. Start Speaking.
      </div>

      {/* Loader */}
      <div className="sp-load" style={{ display: "flex", alignItems: "center", gap: 6 }}>
        {[0, 0.18, 0.36].map((delay, i) => (
          <div key={i} style={{
            width: 5, height: 5, borderRadius: "50%",
            background: "#c9c6be",
            animation: `splashDot 1.2s ease ${delay}s infinite`,
          }} />
        ))}
      </div>

      {/* Bottom version label */}
      <div style={{
        position: "absolute", bottom: 32,
        fontFamily: "'DM Mono', monospace",
        fontSize: 10,
        color: "#c9c6be",
        letterSpacing: "0.08em",
      }}>
        ESTD 1993
      </div>
    </div>
  );
}

