const ALL_FLAT = Object.entries(TOPICS).flatMap(([cat, data]) =>
  data.items.map(item => ({ ...item, category: cat }))
);

const TOPICS_CONTEXT = ALL_FLAT.map((t, i) =>
  `ID${i + 1}|[${t.category}] ${t.title} / ${t.english} — ${t.desc} | ${t.level} | ${t.time}`
).join("\n");

